 0."}],"requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"No requiere sintonización."},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"official-use","name":"Propiedades oficiales","activation":"action","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"held","explanation":"No requiere sintonización."},"target":"Portador","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":1,"effects":[{"id":"consumable-use","kind":"consumable-action","rule":"potion-poison","condition":""}],"execution":{"mode":"automatic","handler":"equipment-consumable","explanation":"Selecciona el objetivo y registra consumo y efecto en una operación. El daño por turno y las salvaciones se resuelven en la ficha del afectado, conservando el estado entre sesiones.","pendingAutomation":[]},"textBlockIds":["official-magic-0","official-magic-1"]}],"recoverySourceIds":["501bce490b79cc8aa574ba66cce3a448135964684e8d940d6c9e835b92e5cbf0","38d9b57cefb0acce0694fb6a0ffc635f97a33ec0418d0ee02953914b11e6821b","fecc8fb4e6d124745fd5267c3c34c2585ee9d2b5b92fb890ef4492e43103dc2d","9e7b38e46c0de594a027d05a3e0794fb3e533ab7341732491bf6e265aea3c1d1"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Cerrar la cobertura de los datos y diferencias antiguos antes de migrar o retirar versiones; las copias y precios comerciales siguen intactos."]}}$native_90ada1798c9bb6dc$::jsonb,true),'{features}',$native_541b5e2a819fefef$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este mejunje parece, huele y sabe como una poción de curación u otra poción beneficiosa. Sin embargo, en realidad es un veneno enmascarado con magia de ilusionismo. Un conjuro identificar revelará su verdadera naturaleza.\n\nSi te bebes la poción, sufrirás 3d6 de d